sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var payload = {};

    try {
        payload = JSON.parse(event.parm2 || '{}');
    } catch (ex) {
        gs.error('DocuMate mail script failed to parse event.parm2: ' + ex.toString());
        payload = {};
    }

    payload.subject = payload.subject || 'DocuMate Document';
    payload.body = payload.body || '';

    payload.to = payload.to || [];
    payload.cc = payload.cc || [];
    payload.bcc = payload.bcc || [];

    email.setSubject(payload.subject);
    template.print(payload.body);

    var i;

    for (i = 0; i < payload.to.length; i++) {
        if (payload.to[i]) {
            email.addAddress('to', payload.to[i], payload.to[i]);
        }
    }

    for (i = 0; i < payload.cc.length; i++) {
        if (payload.cc[i]) {
            email.addAddress('cc', payload.cc[i], payload.cc[i]);
        }
    }

    for (i = 0; i < payload.bcc.length; i++) {
        if (payload.bcc[i]) {
            email.addAddress('bcc', payload.bcc[i], payload.bcc[i]);
        }
    }

    /*
     * Manually copy attachments from DocuMate Instance to sys_email.
     * This is needed because Include Attachments may not copy in this setup.
     */
    try {
        var emailSysId = '';

        if (email && email.getGlideRecord) {
            var emailGr = email.getGlideRecord();
            if (emailGr && emailGr.isValidRecord()) {
                emailSysId = emailGr.getUniqueValue();
            }
        }

        if (!emailSysId && email && email.sys_id) {
            emailSysId = email.sys_id + '';
        }

        if (emailSysId && current && current.isValidRecord()) {
            var sourceAtt = new GlideRecord('sys_attachment');
            sourceAtt.addQuery('table_name', current.getTableName());
            sourceAtt.addQuery('table_sys_id', current.getUniqueValue());
            sourceAtt.query();

            var gsa = new GlideSysAttachment();

            while (sourceAtt.next()) {
                var content = gsa.getContent(sourceAtt);

                if (content !== null && content !== undefined) {
                    var emailGr2 = new GlideRecord('sys_email');

                    if (emailGr2.get(emailSysId)) {
                        gsa.write(
                            emailGr2,
                            sourceAtt.getValue('file_name'),
                            sourceAtt.getValue('content_type'),
                            content
                        );
                    }
                }
            }
        } else {
            gs.warn('DocuMate mail script could not determine sys_email sys_id for attachment copy.');
        }

    } catch (attachEx) {
        gs.error('DocuMate mail script attachment copy failed: ' + attachEx.toString());
    }

})(current, template, email, email_action, event);
